@Test
public void testAccuracy() {
    long[] actualFreq = new long[maxScale];
    CountMinHeavyHitter cmTopK = new CountMinHeavyHitter(fraction, error, confidence, seed);
    for (int i = 0; i < cardinality; i++) {
        int value;
        if (r.nextDouble() < 0.1) {
            value = r.nextInt(10);
        } else {
            value = r.nextInt(maxScale);
        }
        cmTopK.addObject(value);
        actualFreq[value]++;
    }
    long frequency = (long) Math.ceil(cardinality * fraction);
    for (int i = 0; i < actualFreq.length; i++) {
        if (actualFreq[i] > frequency) {
            assertTrue("Heavy Hitter not found :" + i + "," + actualFreq[i], cmTopK.getHeavyHitters().containsKey(i));
        }
    }
    Iterator it = cmTopK.getHeavyHitters().entrySet().iterator();
    while (it.hasNext()) {
        Map.Entry heavyHitter = (Map.Entry) it.next();
        Long estimateError = (Long) heavyHitter.getValue() - actualFreq[(Integer) heavyHitter.getKey()];
        assertTrue("Difference between real frequency and estimate is too large: " + estimateError, estimateError < (error * cardinality));
    }
}

@Test
public void merge() throws CountMinHeavyHitter.CMHeavyHitterMergeException {
    int numToMerge = 5;
    long[] actualFreq = new long[maxScale];
    CountMinHeavyHitter merged = new CountMinHeavyHitter(fraction, error, confidence, seed);
    long totalCardinality = 0;
    CountMinHeavyHitter[] sketches = new CountMinHeavyHitter[numToMerge];
    for (int i = 0; i < numToMerge; i++) {
        CountMinSketch cms = new CountMinSketch(error, confidence, seed);
        sketches[i] = new CountMinHeavyHitter(cms, fraction);
        for (int j = 0; j < cardinality; j++) {
            int val;
            if (r.nextDouble() < 0.1) {
                val = r.nextInt(10);
            } else {
                val = r.nextInt(maxScale);
            }
            sketches[i].addObject(val);
            actualFreq[val]++;
            totalCardinality++;
        }
        merged.merge(sketches[i]);
    }
    Map<Object, Long> mergedHeavyHitters = merged.getHeavyHitters();
    long frequency = (long) (totalCardinality * fraction);
    for (int i = 0; i < actualFreq.length; ++i) {
        if (actualFreq[i] >= frequency) {
            assertTrue("All items with freq. > s.n will be found. Item " + i + ". Real freq. " + actualFreq[i] + " Expected freq." + frequency, mergedHeavyHitters.containsKey(i));
        }
    }
}

@Test
public void testAccuracy() {
    long[] actualFreq = new long[maxScale];
    LossyCounting lossyCounting = new LossyCounting(fraction, error);
    for (int i = 0; i < cardinality; i++) {
        int value;
        if (r.nextDouble() < 0.1) {
            value = r.nextInt(10);
        } else {
            value = r.nextInt(maxScale);
        }
        lossyCounting.addObject(value);
        actualFreq[value]++;
    }
    LOG.debug("Size of heavy hitters: " + lossyCounting.getHeavyHitters().size());
    LOG.debug(lossyCounting.toString());
    Map<Object, Long> heavyHitters = lossyCounting.getHeavyHitters();
    long frequency = (long) Math.ceil(cardinality * fraction);
    long minFrequency = (long) Math.ceil(cardinality * (fraction - error));
    for (int i = 0; i < actualFreq.length; ++i) {
        if (actualFreq[i] >= frequency) {
            assertTrue("All items with freq. > s.n will be found. Item " + i + ". Real freq. " + actualFreq[i] + " Expected freq." + frequency, heavyHitters.containsKey(i));
        }
        if (heavyHitters.containsKey(i)) {
            assertTrue("no item with freq. < (s-e).n will be found. Item " + i + ". Real freq. " + actualFreq[i] + " Min freq." + minFrequency, actualFreq[i] >= minFrequency);
            assertTrue("the estimated freq. underestimates the true freq. by < e.n. Real freq. " + actualFreq[i] + " Lower bound " + heavyHitters.get(i), Math.abs(heavyHitters.get(i) - actualFreq[i]) < error * cardinality);
        }
    }
}

@Test
public void merge() throws HeavyHitterMergeException {
    int numToMerge = 5;
    LossyCounting merged = new LossyCounting(fraction, error);
    LossyCounting[] sketches = new LossyCounting[numToMerge];
    long[] actualFreq = new long[maxScale];
    long totalCardinality = 0;
    for (int i = 0; i < numToMerge; i++) {
        sketches[i] = new LossyCounting(fraction, error);
        for (int j = 0; j < cardinality; j++) {
            int val;
            if (r.nextDouble() < 0.1) {
                val = r.nextInt(10);
            } else {
                val = r.nextInt(maxScale);
            }
            sketches[i].addObject(val);
            actualFreq[val]++;
            totalCardinality++;
        }
        merged.merge(sketches[i]);
    }
    System.out.println("\nMERGED\n" + merged.toString());
    Map<Object, Long> mergedHeavyHitters = merged.getHeavyHitters();
    long frequency = (long) (totalCardinality * fraction);
    long minFrequency = (long) (totalCardinality * (fraction - error));
    System.out.println("Frequency Threshold:" + frequency);
    System.out.println("False positive Threshold:" + minFrequency);
    System.out.println("Frequency of 14:" + actualFreq[14]);
    System.out.println("Real frequent items: ");
    for (int i = 0; i < actualFreq.length; ++i) {
        if (actualFreq[i] >= frequency) {
            System.out.println(i + ": " + actualFreq[i]);
            assertTrue("All items with freq. > s.n will be found. Item " + i + ". Real freq. " + actualFreq[i] + " Expected freq." + frequency, mergedHeavyHitters.containsKey(i));
        }
        if (mergedHeavyHitters.containsKey(i)) {
            assertTrue("no item with freq. < (s-e).n will be found. Item " + i + ". Real freq. " + actualFreq[i] + " Min freq." + minFrequency, actualFreq[i] >= minFrequency);
            assertTrue("the estimated freq. underestimates the true freq. by < e.n. Real freq. " + actualFreq[i] + " Lower bound " + mergedHeavyHitters.get(i), Math.abs(mergedHeavyHitters.get(i) - actualFreq[i]) < error * cardinality);
        }
    }
}

@Test
public void testAccumulatorAllStatistics() throws Exception {
    String input = "";
    Random rand = new Random();
    for (int i = 1; i < 1000; i++) {
        if (rand.nextDouble() < 0.2) {
            input += String.valueOf(rand.nextInt(4)) + "\n";
        } else {
            input += String.valueOf(rand.nextInt(100)) + "\n";
        }
    }
    String inputFile = createTempFile("datapoints.txt", input);
    ExecutionEnvironment env = ExecutionEnvironment.getExecutionEnvironment();
    OperatorStatisticsConfig operatorStatisticsConfig = new OperatorStatisticsConfig(OperatorStatisticsConfig.CountDistinctAlgorithm.HYPERLOGLOG, OperatorStatisticsConfig.HeavyHitterAlgorithm.LOSSY_COUNTING);
    env.readTextFile(inputFile).flatMap(new StringToInt(operatorStatisticsConfig)).output(new DiscardingOutputFormat<Tuple1<Integer>>());
    JobExecutionResult result = env.execute();
    OperatorStatistics globalStats = result.getAccumulatorResult(ACCUMULATOR_NAME);
    System.out.println("Global Stats");
    System.out.println(globalStats.toString());
    OperatorStatistics merged = null;
    Map<String, Object> accResults = result.getAllAccumulatorResults();
    for (String accumulatorName : accResults.keySet()) {
        if (accumulatorName.contains(ACCUMULATOR_NAME + "-")) {
            OperatorStatistics localStats = (OperatorStatistics) accResults.get(accumulatorName);
            LOG.debug("Local Stats: " + accumulatorName);
            LOG.debug(localStats.toString());
            if (merged == null) {
                merged = localStats.clone();
            } else {
                merged.merge(localStats);
            }
        }
    }
    LOG.debug("Local Stats Merged: \n");
    LOG.debug(merged.toString());
    Assert.assertEquals("Global cardinality should be 999", 999, globalStats.cardinality);
    Assert.assertEquals("Count distinct estimate should be around 100 and is " + globalStats.estimateCountDistinct(), 100.0, (double) globalStats.estimateCountDistinct(), 5.0);
    Assert.assertTrue("The total number of heavy hitters should be between 0 and 5.", globalStats.getHeavyHitters().size() > 0 && globalStats.getHeavyHitters().size() <= 5);
    Assert.assertEquals("Min when merging the local accumulators should correspond with min" + "of the global accumulator", merged.getMin(), globalStats.getMin());
    Assert.assertEquals("Max resulting from merging the local accumulators should correspond to" + "max of the global accumulator", merged.getMax(), globalStats.getMax());
    Assert.assertEquals("Count distinct when merging the local accumulators should correspond to " + "count distinct in the global accumulator", merged.estimateCountDistinct(), globalStats.estimateCountDistinct());
    Assert.assertEquals("The number of heavy hitters when merging the local accumulators should correspond " + "to the number of heavy hitters in the global accumulator", merged.getHeavyHitters().size(), globalStats.getHeavyHitters().size());
}

