        assertEquals(1, buf1.position());
        assertEquals(3, buf1.limit());
        assertEquals(3, buf2.position());
        assertEquals(7, buf2.limit());
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

