@Test
public void testVariableLengthStringBuildAndRetrieve() {
    try {
        final int NUM_MEM_PAGES = 40 * NUM_PAIRS / PAGE_SIZE;
        MutableObjectIterator<StringPair> buildInput = new UniformStringPairGenerator(NUM_PAIRS, 1, false);
        MutableObjectIterator<StringPair> probeTester = new UniformStringPairGenerator(NUM_PAIRS, 1, false);
        MutableObjectIterator<StringPair> updater = new UniformStringPairGenerator(NUM_PAIRS, 1, false);
        MutableObjectIterator<StringPair> updateTester = new UniformStringPairGenerator(NUM_PAIRS, 1, false);
        AbstractMutableHashTable<StringPair> table = new CompactingHashTable<StringPair>(serializerS, comparatorS, getMemory(NUM_MEM_PAGES, PAGE_SIZE));
        table.open();
        StringPair target = new StringPair();
        while (buildInput.next(target) != null) {
            table.insert(target);
        }
        AbstractHashTableProber<StringPair, StringPair> prober = table.getProber(comparatorS, pairComparatorS);
        StringPair temp = new StringPair();
        while (probeTester.next(target) != null) {
            assertNotNull("" + target.getKey(), prober.getMatchFor(target, temp));
            assertEquals(temp.getValue(), target.getValue());
        }
        while (updater.next(target) != null) {
            target.setValue(target.getValue());
            table.insertOrReplaceRecord(target);
        }
        while (updateTester.next(target) != null) {
            assertNotNull(prober.getMatchFor(target, temp));
            assertEquals(target.getValue(), temp.getValue());
        }
        table.close();
        assertEquals("Memory lost", NUM_MEM_PAGES, table.getFreeMemory().size());
    } catch (Exception e) {
        e.printStackTrace();
        fail("Error: " + e.getMessage());
    }
}

@Test
public void compareMutableHashTablePerformance1() throws IOException {
    // ----------------------------------------------90% filtered during probe spill phase-----------------------------------------
    // create a build input with 1000000 records with key spread between [0 -- 10000000] with step of 10 for nearby records.
    int buildSize = 1000000;
    int buildStep = 10;
    int buildScope = buildStep * buildSize;
    // create a probe input with 5000000 records with key spread between [0 -- 1000000] with distance of 1 for nearby records.
    int probeSize = 5000000;
    int probeStep = 1;
    int probeScope = buildSize;
    int expectedResult = 500000;
    long withBloomFilterCost = hybridHashJoin(buildSize, buildStep, buildScope, probeSize, probeStep, probeScope, expectedResult, true);
    long withoutBloomFilterCost = hybridHashJoin(buildSize, buildStep, buildScope, probeSize, probeStep, probeScope, expectedResult, false);
    System.out.println("HybridHashJoin2:");
    System.out.println("Build input size: " + 100 * buildSize);
    System.out.println("Probe input size: " + 100 * probeSize);
    System.out.println("Available memory: " + this.memManager.getMemorySize());
    System.out.println("Probe record be filtered before spill: " + (1 - (double) probeScope / buildScope) * 100 + "% percent.");
    System.out.println(String.format("Cost: without bloom filter(%d), with bloom filter(%d)", withoutBloomFilterCost, withBloomFilterCost));
}

