@Test
public void testTraversableOnce() {
    try {
        UnionIterator<Integer> iter = new UnionIterator<>();
        // should succeed
        iter.iterator();
        // should fail
        try {
            iter.iterator();
            fail("should fail with an exception");
        } catch (TraversableOnceException e) {
            // expected
        }
        // should fail again
        try {
            iter.iterator();
            fail("should fail with an exception");
        } catch (TraversableOnceException e) {
            // expected
        }
        // reset the thing, keep it empty
        iter.clear();
        // should succeed
        iter.iterator();
        // should fail
        try {
            iter.iterator();
            fail("should fail with an exception");
        } catch (TraversableOnceException e) {
            // expected
        }
        // should fail again
        try {
            iter.iterator();
            fail("should fail with an exception");
        } catch (TraversableOnceException e) {
            // expected
        }
        // reset the thing, add some data
        iter.clear();
        iter.addList(Arrays.asList(1, 2, 3, 4, 5, 6, 7));
        // should succeed
        Iterator<Integer> ints = iter.iterator();
        assertNotNull(ints.next());
        assertNotNull(ints.next());
        assertNotNull(ints.next());
        // should fail if called in the middle of operations
        try {
            iter.iterator();
            fail("should fail with an exception");
        } catch (TraversableOnceException e) {
            // expected
        }
        // reset the thing, keep it empty
        iter.clear();
        // should succeed again
        assertFalse(iter.iterator().hasNext());
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

@Test
public void testZooKeeperEnsembleConnectStringConfiguration() throws Exception {
    // ZooKeeper does not like whitespace in the quorum connect String.
    String actual, expected;
    Configuration conf = new Configuration();
    {
        expected = "localhost:2891";
        setQuorum(conf, expected);
        actual = ZooKeeperUtils.getZooKeeperEnsemble(conf);
        assertEquals(expected, actual);
        // with leading and trailing whitespace
        setQuorum(conf, " localhost:2891 ");
        actual = ZooKeeperUtils.getZooKeeperEnsemble(conf);
        assertEquals(expected, actual);
        // whitespace after port
        setQuorum(conf, "localhost :2891");
        actual = ZooKeeperUtils.getZooKeeperEnsemble(conf);
        assertEquals(expected, actual);
    }
    {
        expected = "localhost:2891,localhost:2891";
        setQuorum(conf, "localhost:2891,localhost:2891");
        actual = ZooKeeperUtils.getZooKeeperEnsemble(conf);
        assertEquals(expected, actual);
        setQuorum(conf, "localhost:2891, localhost:2891");
        actual = ZooKeeperUtils.getZooKeeperEnsemble(conf);
        assertEquals(expected, actual);
        setQuorum(conf, "localhost :2891, localhost:2891");
        actual = ZooKeeperUtils.getZooKeeperEnsemble(conf);
        assertEquals(expected, actual);
        setQuorum(conf, " localhost:2891, localhost:2891 ");
        actual = ZooKeeperUtils.getZooKeeperEnsemble(conf);
        assertEquals(expected, actual);
    }
}

