@Test
public void testSlidingWindow() {
    final ScheduledExecutorService timerService = Executors.newSingleThreadScheduledExecutor();
    try {
        final CollectingOutput<Integer> out = new CollectingOutput<>(50);
        final Object lock = new Object();
        final StreamTask<?, ?> mockTask = createMockTaskWithTimer(timerService, lock);
        // tumbling window that triggers every 20 milliseconds
        AccumulatingProcessingTimeWindowOperator<Integer, Integer, Integer> op = new AccumulatingProcessingTimeWindowOperator<>(validatingIdentityFunction, identitySelector, IntSerializer.INSTANCE, IntSerializer.INSTANCE, 150, 50);
        op.setup(mockTask, new StreamConfig(new Configuration()), out);
        op.open();
        final int numElements = 1000;
        for (int i = 0; i < numElements; i++) {
            synchronized (lock) {
                op.processElement(new StreamRecord<Integer>(i));
            }
            Thread.sleep(1);
        }
        synchronized (lock) {
            op.close();
        }
        op.dispose();
        // get and verify the result
        List<Integer> result = out.getElements();
        // if we kept this running, each element would be in the result three times (for each slide).
        // we are closing the window before the final panes are through three times, so we may have less
        // elements.
        if (result.size() < numElements || result.size() > 3 * numElements) {
            fail("Wrong number of results: " + result.size());
        }
        Collections.sort(result);
        int lastNum = -1;
        int lastCount = -1;
        for (int num : result) {
            if (num == lastNum) {
                lastCount++;
                assertTrue(lastCount <= 3);
            } else {
                lastNum = num;
                lastCount = 1;
            }
        }
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    } finally {
        timerService.shutdown();
    }
}

