@Test
@SuppressWarnings("unchecked")
public void testContinuousWatermarkTrigger() throws Exception {
    closeCalled.set(0);
    final int WINDOW_SIZE = 3;
    WindowOperator<String, Tuple2<String, Integer>, Tuple2<String, Integer>, GlobalWindow> operator = new WindowOperator<>(GlobalWindows.create(), new TupleKeySelector(), windowBufferFactory, new ReduceWindowFunction<String, GlobalWindow, Tuple2<String, Integer>>(new SumReducer()), ContinuousWatermarkTrigger.of(Time.of(WINDOW_SIZE, TimeUnit.SECONDS)));
